use verus::prelude::*;

#[ensures(result@ == a@.rev())]
fn reverse(a: Vec<char>) -> Vec<char> {
    // We can consume the input Vec and use its iterator in reverse order,
    // then collect the characters back into a new Vec<char>.
    a.into_iter().rev().collect()
}

